static int average(int[] values) {
    if (values == null || values.length == 0) return 0;
    int total = 0;
    for (int value : values) total += value;
    return total / values.length;
}
System.out.println(average(new int[]{2, 4, 6}));

static boolean contains(int[] values, int target, int i) {
    if (i >= values.length) return false;
    if (values[i] == target) return true;
    return contains(values, target, i + 1);
}
System.out.println(contains(new int[]{1, 3, 5}, 3, 0));

static int divide(int numerator, int denominator) {
    if (denominator == 0) throw new IllegalArgumentException("denominator cannot be zero");
    return numerator / denominator;
}
System.out.println(divide(3, 4));

static int[] doubled(int[] values) {
    int[] result = new int[values.length];
    for (int i = 0; i < values.length; i++) result[i] = values[i] * 2;
    return result;
}
System.out.println(doubled(new int[]{1, 2})[1]);

static int power(int base, int exp) {
    if (exp == 0) return 1;
    return base * power(base, exp - 1);
}
System.out.println(power(5, 8));

static String levelName(int level) {
    if (level < 1) return "Invalid";
    if (level == 1) return "Beginner";
    if (level == 2) return "Explorer";
    return "Detective";
}
System.out.println(levelName(6));

static int countDown(int n) {
    if (n <= 0) return 0;
    return 1 + countDown(n - 1);
}
System.out.println(countDown(7));
